"""Actual terminal human conversations on Hoenn routes and town exteriors."""
ROWS = []
def add(key, labels, subject, lines):
    replies = [s.strip() for s in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='hoenn_field_' + key, labels=labels.split(), subject=subject, replies=replies))

